contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll attempt to call getFirstWithdrawalBonus for an arbitrary recipient address
    // and assert the general rule: if the call succeeds then the bonus was paid and
    // claimed (observed via effects on contract balance and withdraw behaviour),
    // otherwise it reverted (e.g., because already claimed) — so either revert or
    // the contract balance decreased by 100 and subsequent calls do not pay again.

    function run(address recipient, uint topup) public payable {
        require(address(this).balance >= topup, "insufficient balance for topup");
        // fund the contract with some Ether so it can pay out the 100 bonus
        // only do the funding if topup > 0
        if (topup > 0) {
            (bool s, ) = address(c).call{value: topup}("");
            // we don't require success because some test harnesses may not forward
            // but we still proceed; the property must hold regardless
        }

        uint balBefore = address(c).balance;

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        // Now formulate the property: either the call reverted, or it succeeded and
        // (1) the contract's balance decreased by exactly 100 (it paid the bonus), and
        // (2) a subsequent call to getFirstWithdrawalBonus for the same recipient must revert
        //    (since claimedBonus should be true and bonus isn't reissued).

        bool subsequentReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            subsequentReverted = false;
        } catch {
            subsequentReverted = true;
        }

        assert(
            reverted || (
                // If succeeded, contract paid out exactly 100 (or at least attempted to).
                // Use <= check to allow for situations where payment failed causing revert earlier,
                // but since we are in the succeeded branch, require exact decrease of 100.
                balBefore >= 100 && balBefore - balAfter == 100 &&
                // and subsequent call must revert (bonus can only be claimed once)
                subsequentReverted
            )
        );
    }

    receive() external payable {}
}

