contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call getFirstWithdrawalBonus with arbitrary recipient.
    // The test checks two things: if the call succeeds then the recipient's balance increases by 100
    // (because the contract adds 100 to rewardsForA[recipient] then withdraws it), and in all cases
    // the SmartFix reentrancy lock (_locked) is false when observed after the call.

    function run(address payable recipient) public payable {
        require(recipient != address(0));

        // record balances before
        uint beforeRecipient = recipient.balance;
        uint beforeContract = address(c).balance;

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable _locked flag
        bool locked = c._locked();

        // If the call did not revert, then recipient must have received exactly 100 wei
        // and the contract balance must have decreased by 100 (or increased if recipient is the contract,
        // but recipient can't be the contract here because msg.sender for c calls is this test contract).
        // We express the general rule: either reverted is true, or recipient.balance == before + 100.
        // Additionally, in all cases _locked must be false.
        assert((reverted || recipient.balance == beforeRecipient + 100) && locked == false);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call getFirstWithdrawalBonus on any recipient (not zero address) and observe outcomes.
    // We assert: if the call does not revert then _locked == false afterwards and
    // address(c).balance >= beforeBalance - 100 (i.e., contract does not lose more than 100 wei).
    function run(address payable recipient) public payable {
        require(recipient != address(0));

        uint beforeContractBalance = address(c).balance;

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool locked = c._locked();
        uint afterContractBalance = address(c).balance;

        // If the call succeeded (did not revert) then the lock must be cleared and
        // the contract's balance must not have decreased by more than 100 wei.
        assert(reverted || (locked == false && afterContractBalance + 100 >= beforeContractBalance));
    }

    receive() external payable {}
}

